create or replace function public.factory_claim_next_run(p_worker_id text) returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_run public.factory_runs%rowtype;v_task public.factory_tasks%rowtype;v_project public.factory_projects%rowtype;begin if nullif(btrim(p_worker_id),'') is null then raise exception 'worker_id is required';end if;select r.* into v_run from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.status in ('created','queued') and t.status='queued' order by r.created_at for update of r skip locked limit 1;if v_run.id is null then return null;end if;select * into v_task from public.factory_tasks where id=v_run.task_id for update;select * into v_project from public.factory_projects where id=v_task.project_id;update public.factory_runs set status='running',started_at=coalesce(started_at,now()),metadata=metadata||jsonb_build_object('worker_id',p_worker_id,'claimed_at',now()) where id=v_run.id;update public.factory_tasks set status='running',updated_at=now() where id=v_task.id;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project.id,v_task.id,v_run.id,'system',p_worker_id,'run.claimed','{}'::jsonb);return jsonb_build_object('run_id',v_run.id,'task_id',v_task.id,'project_id',v_project.id,'project_key',v_project.project_key,'stages',coalesce(v_run.metadata->'stages','[]'::jsonb),'context',jsonb_build_object('task',v_task.description,'manifest',v_project.manifest));end;$$;
revoke all on function public.factory_claim_next_run(text) from public,anon,authenticated;grant execute on function public.factory_claim_next_run(text) to service_role;

create or replace function public.factory_record_runtime_stage(p_run_id uuid,p_stage text,p_status text,p_output jsonb) returns void language plpgsql security invoker set search_path='' as $$ declare v_task_id uuid;v_project_id uuid;begin select r.task_id,t.project_id into v_task_id,v_project_id from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.id=p_run_id;if v_task_id is null then raise exception 'run not found';end if;update public.factory_runs set metadata=jsonb_set(metadata,array['stage_evidence',p_stage],jsonb_build_object('status',p_status,'output',coalesce(p_output,'{}'::jsonb),'recorded_at',now()),true) where id=p_run_id;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project_id,v_task_id,p_run_id,'system','runtime-worker','run.stage.recorded',jsonb_build_object('stage',p_stage,'status',p_status));end;$$;
revoke all on function public.factory_record_runtime_stage(uuid,text,text,jsonb) from public,anon,authenticated;grant execute on function public.factory_record_runtime_stage(uuid,text,text,jsonb) to service_role;

create or replace function public.factory_finish_run(p_run_id uuid,p_status text,p_error text default null) returns void language plpgsql security invoker set search_path='' as $$ declare v_task_id uuid;v_project_id uuid;v_task_status text;begin if p_status not in ('completed','failed') then raise exception 'invalid terminal status';end if;select r.task_id,t.project_id into v_task_id,v_project_id from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.id=p_run_id for update of r;if v_task_id is null then raise exception 'run not found';end if;v_task_status:=case when p_status='completed' then 'completed' else 'failed' end;update public.factory_runs set status=p_status,finished_at=now(),metadata=case when p_error is null then metadata else metadata||jsonb_build_object('error',p_error) end where id=p_run_id;update public.factory_tasks set status=v_task_status,updated_at=now() where id=v_task_id;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project_id,v_task_id,p_run_id,'system','runtime-worker','run.'||p_status,jsonb_build_object('error',p_error));end;$$;
revoke all on function public.factory_finish_run(uuid,text,text) from public,anon,authenticated;grant execute on function public.factory_finish_run(uuid,text,text) to service_role;
